mapper.update:
UPDATE oc_shipping_order
SET shipping_status = #{toStatus},
    express_company = #{expressCompany},
    express_no = #{expressNo},
    shipping_time = #{shippingTime},
    update_time = #{shippingTime}
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND shipping_no = #{shippingNo}
  AND shipping_status = #{fromStatus}

UPDATE oc_shipping_order
SET shipping_status = #{toStatus},
    receive_time = #{receiveTime},
    update_time = #{receiveTime}
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND order_no = #{orderNo}
  AND shipping_status = #{fromStatus}
